import React from 'react';
import { FormattedMessage, useIntl } from 'react-intl';

import { PageHeader, StickyScrollWithFilters } from 'components';
import { WATCH_TOWER_FILTER_CATEGORIES } from 'components/Filter/config/filterCategories';
import { StyledGridContainer, StyledHomeContainer } from 'shared/Styles';

import {
  WATCH_TOWER_MAX_VISIBLE_FILTERS,
  WATCH_TOWER_PAGE_NAME,
  WATCH_TOWER_VISIBLE_FILTER_FIELDS,
} from './constants';
import { useWatchTowerFilterMock } from './hooks/useWatchTowerFilterMock';

const richText = {
  b: (chunks: React.ReactNode) => <b>{chunks}</b>,
};

export const WatchTower = () => {
  const { formatMessage } = useIntl();
  const isFilterMockReady = useWatchTowerFilterMock();

  const pageTitle = formatMessage({
    id: 'ValueCreation.WatchTower.title',
  });

  if (!isFilterMockReady) {
    return null;
  }

  return (
    <>
      <StickyScrollWithFilters
        dataTestId="watch-tower-container"
        filter={{
          pageName: WATCH_TOWER_PAGE_NAME,
          visibleFields: [...WATCH_TOWER_VISIBLE_FILTER_FIELDS],
          maxVisibleFilters: WATCH_TOWER_MAX_VISIBLE_FILTERS,
          hidden: false,
          filterCategories: WATCH_TOWER_FILTER_CATEGORIES,
        }}
        breadcrumbs={{
          pageList: [
            { href: '/value-creation', pageName: 'Value Creation' },
            {
              href: '/value-creation/watch-tower',
              pageName: pageTitle,
            },
          ],
          showIcon: true,
        }}
        isResponsivePage
      />

      <StyledGridContainer isResponsivePage>
        <StyledHomeContainer>
          <PageHeader
            title={pageTitle}
            subtitle={
              <FormattedMessage
                id="ValueCreation.WatchTower.subtitle"
                values={richText}
              />
            }
            loading={false}
          />
        </StyledHomeContainer>
      </StyledGridContainer>
    </>
  );
};
